<script setup lang="ts">
import { computed, ref } from 'vue';
import { t } from '../../i18n';
import type { PdbReference } from '../../v2/workbench';
import ReviewHint from './ReviewHint.vue';
import ResearchProfile from './ResearchProfile.vue';
import { abstractStatusLabels, type ResearchProfile as ResearchProfileData } from './articleMetadata';
const props=defineProps<{metadata:{abstract?:string|null;abstract_source?:string|null;pdb_references?:PdbReference[];pmid?:string|null;pmcid?:string|null;identifiers_source?:string|null;abstract_status?:keyof typeof abstractStatusLabels;abstract_note?:string|null;research_profile?:ResearchProfileData}}>();
const issue=computed(()=>props.metadata.abstract_status==='not_found'||props.metadata.abstract_status==='needs_review');
const expanded=ref(false);
const usageLabels = {this_work:'本文结构',cited_structure:'引用结构',unknown:'用途待核对'};
</script>
<template><section class="article-metadata"><div v-if="metadata.pmid || metadata.pmcid" class="identifier-links"><a v-if="metadata.pmid" data-pmid-link :href="`https://pubmed.ncbi.nlm.nih.gov/${encodeURIComponent(metadata.pmid)}/`" target="_blank" rel="noopener">PMID: {{metadata.pmid}} ↗</a><a v-if="metadata.pmcid" :href="`https://pmc.ncbi.nlm.nih.gov/articles/${encodeURIComponent(metadata.pmcid)}/`" target="_blank" rel="noopener">PMCID: {{metadata.pmcid}} ↗</a></div>
<h3>Abstract</h3><div v-if="issue" class="abstract-issue"><p data-abstract-status>{{t(abstractStatusLabels[metadata.abstract_status!])}}</p><p v-if="metadata.abstract_note">{{metadata.abstract_note}}</p></div><p class="preserve-lines" :class="{'abstract-preview':!expanded && (metadata.abstract?.length??0)>1400}" data-article-abstract>{{ metadata.abstract || (metadata.abstract_status === 'not_found' ? '—' : t('尚未记录摘要')) }}</p><button v-if="(metadata.abstract?.length??0)>1400" type="button" class="button-quiet" :aria-expanded="expanded" @click="expanded=!expanded">{{t(expanded?'收起摘要':'展开完整摘要')}}</button>
<ResearchProfile v-if="metadata.research_profile" :profile="metadata.research_profile" /><h3>PDB</h3><p v-if="!metadata.pdb_references?.length">{{ t('尚未记录 PDB ID；空白不表示文章一定未报告。') }}</p><ul v-else class="pdb-list"><li v-for="(entry,index) in metadata.pdb_references" :key="index"><a :href="`https://www.rcsb.org/structure/${encodeURIComponent(entry.pdb_id)}`" target="_blank" rel="noopener">{{ entry.pdb_id }} ↗</a> · {{ t(usageLabels[entry.usage]) }}<span v-if="entry.compound_label"> · Compound {{ entry.compound_label }}</span><ReviewHint :hint="entry.review_hint" /><details v-if="entry.source_page || entry.source_context || entry.review_hint"><summary>{{t('依据与说明')}}</summary><p v-if="entry.source_page">p. {{entry.source_page}}</p><p v-if="entry.source_context">{{ entry.source_context }}</p><p v-if="entry.review_hint">{{entry.review_hint}}</p></details></li></ul></section></template>
<style scoped>.identifier-links{display:flex;flex-wrap:wrap;gap:.5rem 1rem}.article-metadata{overflow-wrap:anywhere}.abstract-preview{display:-webkit-box;-webkit-line-clamp:8;-webkit-box-orient:vertical;overflow:hidden}.abstract-issue{border-left:3px solid var(--amber);padding-left:.7rem}.pdb-list{list-style:none;padding:0;display:grid;gap:.5rem}.pdb-list li{border:1px solid var(--line);border-radius:6px;padding:.7rem}details{margin-top:.5rem}summary{cursor:pointer;color:var(--ink-muted);font-size:.85rem}</style>
